<template>
  <div id="symmetryUI" :style="panelStyle">
    <span class="UIheader">symmetries</span><br>

    <es-button name="none" :selected="cursym" @bclick="changeSym" hint="NO symmetry"></es-button>
    <es-button name="rosette" :selected="cursym" @bclick="changeSym" hint="rosette / flower symmetry"></es-button>
    <span :style="showPointParams">
      <es-numfield param="Nrot" :val="symmState.Nrot" size="2" @numchange="update"></es-numfield>
      <es-numfield param="Nref" :val="symmState.Nref" size="2" @numchange="update"></es-numfield>
      <!--<es-numfield param="rot" label="&theta;" :val="rot" @numchange="update"></es-numfield>-->
    </span>
    <br>
    <!--Rotation Free<br>-->
    <es-button name="p1" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="hexgrid" :selected="cursym" @bclick="changeSym">p1<i>hex</i></es-button>
    <es-button name="diagonalgrid" :selected="cursym" @bclick="changeSym">p1<i>diag</i></es-button>
    <es-button name="pm" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="cm" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="pg" :selected="cursym" @bclick="changeSym"></es-button><br>
    <!--<br>180&deg;</br>-->
    <es-button name="pmg" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="pgg" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="pmm" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="p2" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="cmm" :selected="cursym" @bclick="changeSym"></es-button><br>
    <!--<br>Square<br>-->
    <es-button name="p4" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="p4g" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="p4m" :selected="cursym" @bclick="changeSym"></es-button><br>
    <!--<br>Hexagonal<br>-->
    <es-button name="p3" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="p6" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="p31m" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="p3m1" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="p6m" :selected="cursym" @bclick="changeSym"></es-button><br>

    <es-button name="*237" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="*238" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="237" :selected="cursym" @bclick="changeSym"></es-button>
    <es-button name="238" :selected="cursym" @bclick="changeSym"></es-button><br>
    <es-button name="*pqr" :selected="cursym" @bclick="changeSym"
               hint="hyperbolic group *pqr with mirrors, for the p, q, r typed here">*<i>pqr</i></es-button>
    <es-button name="pqr" :selected="cursym" @bclick="changeSym"
               hint="hyperbolic group pqr, rotations only"><i>pqr</i></es-button>
    <es-numfield param="p" :val="symmState.p" size="2" @numchange="updateTriple"></es-numfield>
    <es-numfield param="q" :val="symmState.q" size="2" @numchange="updateTriple"></es-numfield>
    <es-numfield param="r" :val="symmState.r" size="2" @numchange="updateTriple"></es-numfield>
    <br>
    <span v-if="tripleError" class="tripleError">{{tripleError}}<br></span>
    <template v-if="triple">
      center
      <es-button v-for="{n, i} in centerButtons" :key="i" :name="String(i)"
                 :selected="String(symmState.center || 0)" @bclick="changeCenter"
                 :hint="'put an order-' + n + ' vertex of the triangle at the center of the disk'">{{n}}</es-button>
      <br>
    </template>

    <es-button name="grid" :selected="curtool" @bclick="toggleGridTool" hint="toggle symmetry grid adjustment tool">
      grid adjust
    </es-button>

    <template v-if="options.showGridParameters">
      <es-numfield param="X" :val="symmState.x" size="4" @numchange="update"></es-numfield>
      <es-numfield param="Y" :val="symmState.y" size="4" @numchange="update"></es-numfield>
    </template>
    <span :style="showGridParams">
      <template v-if="options.showGridParameters">
        <template v-if="!options.dynamicGridSize">
          <es-numfield param="Nx" :val="symmState.Nx" @numchange="update" size="2"></es-numfield>
          <es-numfield param="Ny" :val="symmState.Ny" @numchange="update" size="2"></es-numfield><br>
        </template>
        <es-numfield param="d" label="&Delta;" :val="symmState.d" size="3" @numchange="update"></es-numfield>
      </template>
      <es-button name="halvegrid" @bclick="halveD" hint="halve symmetry grid size">&#189;</es-button>
      <es-button name="doublegrid" @bclick="doubleD" hint="double symmetry grid size">2x</es-button>
      <!--
      <div class="button" @click="halveD">&#189;</div>
      <div class="button" @click="doubleD">2x</div>-->
    </span><br>

  </div>
</template>

<script>
import es_numfield from './es_numfield';
import es_button from './es_button';
import {gS} from '../main.js';
import {planarSymmetries, hyperbolicSpec, hyperbolicTriple, customHyperbolicSyms,
  triangleGroupError} from '../symmetryGenerator';

import _ from 'underscore';

export default {
  props: ['symmState','params', 'options'],
  components: {
    'es-button': es_button,
    'es-numfield': es_numfield
  },
  data: function(){ return {tripleError: ""}; },
  computed: {
    cursym: function(){ return this.symmState.sym; },
    triple: function(){ return hyperbolicTriple(this.symmState); },
    // the triangle's vertex orders, with their indices (0, 1, 2 for p, q, r); ascending for the
    // presets, to match their names, and as typed for the custom groups
    centerButtons: function(){
      const t = this.triple;
      const buttons = [t.p, t.q, t.r].map((n, i) => ({n: n, i: i}));
      return customHyperbolicSyms.includes(this.symmState.sym) ? buttons : _.sortBy(buttons, 'n');
    },
    curtool: function(){ return this.params.curTool; },
    showPointParams: function(){
      return {visibility: this.symmState.sym == "rosette" ? "visible" : "hidden"};
    },
    showGridParams: function(){
      return {visibility:
               Object.keys(planarSymmetries).includes(this.symmState.sym) ? "visible" : "hidden"
             };
    },
    panelStyle: function() {
      return {display: this.params.showSymm ? "block" : "none"};
    }
  },
  methods: {
    changeSym: function(symname){ gS.$emit('symmUpdate', {sym: symname}); },
    toggleGridTool: function(toolName){
      if(gS.params.curTool == toolName){ //toolName == "grid"
        gS.$emit('toolUpdate', gS.params.lastTool);
      } else {
        gS.$emit('toolUpdate', toolName);
      }
    },
    update: function(name, val){
      var gridcopy = _.clone(gS.symmState);
      gridcopy[name] = Number(val);
      gS.$emit('symmUpdate', gridcopy);
    },
    // Typing p, q or r switches to the custom group, keeping mirrors unless the current group is
    // a rotation-only hyperbolic one. An invalid triple is rejected and the field restored.
    updateTriple: function(name, val){
      const triple = _.pick(gS.symmState, 'p', 'q', 'r');
      triple[name] = Number(val);
      const err = triangleGroupError(triple.p, triple.q, triple.r);
      if(err){
        this.tripleError = err;
        this.$el.querySelector(`input[name="${name}"]`).value = gS.symmState[name];
        return;
      }
      this.tripleError = "";
      const cur = hyperbolicSpec(gS.symmState);
      const sym = (cur && !cur.mirror) ? 'pqr' : '*pqr';
      gS.$emit('symmUpdate', _.assign({sym: sym}, triple));
    },
    changeCenter: function(i){ gS.$emit('symmUpdate', {center: Number(i)}); },
    halveD: function(){ this.update("d", this.symmState.d/2.0); },
    doubleD: function(){ this.update("d", this.symmState.d*2.0); },
  },
}
</script>
<style scoped>
.tripleError {
  color: #b33;
  font-size: 85%;
}
</style>
